// src/js/Chat/Emoji/EmojiParser.js

import twemoji from "twemoji";

export function emojify(text) {
  if (!text) return text;
  return twemoji.parse(text, {
    folder: "svg",
    ext: ".svg",
    base: "https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/",
    className: "twemoji"
  });
}
